27	func New(checkDatabase func(context.Context) error, service Service) http.Handler {
28		mux := http.NewServeMux()
29		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
30			respond(w, http.StatusOK, `{"status":"ok"}`)
31		})
32		mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
33			ctx, cancel := context.WithTimeout(r.Context(), time.Second)
34			defer cancel()
35			if err := checkDatabase(ctx); err != nil {
36				respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
37				return
38			}
39			respond(w, http.StatusOK, `{"status":"ready"}`)
40		})
41	
42		h := &handlers{service: service}
43		mux.HandleFunc("POST /entitlements", h.createEntitlement)
44		mux.HandleFunc("GET /entitlements/{entitlementID}", h.getEntitlement)
45		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations", h.createReservation)
46		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/confirm", h.settle(entitlements.ActionConfirm))
47		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/release", h.settle(entitlements.ActionRelease))
48		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/reverse", h.reverseReservation)
49		mux.HandleFunc("POST /entitlements/{entitlementID}/adjustments", h.createAdjustment)
50		mux.HandleFunc("POST /entitlements/{entitlementID}/reschedules", h.createReschedule)
51		mux.HandleFunc("POST /entitlements/{entitlementID}/seat-adjustments", h.createSeatAdjustment)
52		mux.HandleFunc("POST /entitlements/{entitlementID}/pauses", h.pauseEntitlement)
53		mux.HandleFunc("POST /entitlements/{entitlementID}/resumes", h.resumeEntitlement)
54		return mux
55	}
