69	func (h *handlers) createEntitlement(w http.ResponseWriter, r *http.Request) {
70		var req createEntitlementRequest
71		if !decode(w, r, &req) {
72			return
73		}
74		validFrom, errFrom := time.Parse(time.RFC3339, req.ValidFrom)
75		validTo, errTo := time.Parse(time.RFC3339, req.ValidTo)
76		if req.ValidFrom == "" || req.ValidTo == "" || errFrom != nil || errTo != nil {
77			respondError(w, &entitlements.Error{
78				Code:    entitlements.CodeInvalidRequest,
79				Message: "valid_from and valid_to must be RFC 3339 timestamps, e.g. 2026-01-01T00:00:00Z",
80			})
81			return
82		}
83		ent, err := h.service.CreateEntitlement(r.Context(), entitlements.CreateEntitlementInput{
84			EntitlementID: req.EntitlementID,
85			SeatsTotal:    req.SeatsTotal,
86			QuotaTotal:    req.QuotaTotal,
87			ValidFrom:     validFrom,
88			ValidTo:       validTo,
89		})
90		if err != nil {
91			respondError(w, err)
92			return
93		}
94		respondJSON(w, http.StatusCreated, ent)
95	}
