161			{"insufficient quota", entitlements.CodeInsufficientQuota, 422},
162			{"missing reservation", entitlements.CodeReservationNotFound, 404},
163			{"param mismatch", entitlements.CodeReservationParamChanged, 409},
164			{"already settled", entitlements.CodeReservationSettled, 409},
165			{"not confirmed", entitlements.CodeReservationNotConfirmed, 422},
166			{"already reversed", entitlements.CodeReservationReversed, 409},
167			{"adjustment param mismatch", entitlements.CodeAdjustmentParamChanged, 409},
168			{"reschedule param mismatch", entitlements.CodeRescheduleParamChanged, 409},
169			{"seat adjustment param mismatch", entitlements.CodeSeatAdjustmentChanged, 409},
170			{"closed", entitlements.CodeEntitlementClosed, 409},
171			{"pause/resume param mismatch", entitlements.CodePauseResumeParamChanged, 409},
172			{"paused", entitlements.CodeEntitlementPaused, 422},
173			{"already paused", entitlements.CodeEntitlementAlreadyPaused, 409},
174			{"not paused", entitlements.CodeEntitlementNotPaused, 409},
175			{"internal", "unmapped", 500},
176		} {
177			t.Run(tc.name, func(t *testing.T) {
178				service := &fakeService{err: &entitlements.Error{Code: tc.code, Message: "boom"}}
