184					t.Fatalf("error code %q missing from body %q", tc.code, response.Body.String())
185				}
186				if strings.Contains(response.Body.String(), "boom") && tc.code == "unmapped" {
187					t.Fatal("internal error detail leaked")
188				}
189			})
190		}
191	}
