func TestDepartmentRecordRoutes(t *testing.T) {
	allocation := entitlements.DepartmentRecord{
		RecordID: "alloc-1", DepartmentID: "dept-9", Amount: 30,
		Kind: entitlements.KindAllocation, CreatedAt: time.Now(),
	}
